# Re-parse the context more carefully to extract the actual graph and operation
# The context has a structured format: first part describes the task, then the graph edges, then the operation

# Split the context into parts
parts = context.strip().split('\n\n')
# The first part is the description, the second part is the graph edges, the third is the operation
# But the actual structure is: description, then "The graph has the following edges:", then edges, then "Operation:"

# Find where the graph edges start and end
graph_start = -1
graph_end = -1
operation_start = -1

for i, part in enumerate(parts):
    if "The graph has the following edges:" in part:
        graph_start = i
    if "Operation:" in part:
        operation_start = i

# Extract the graph edges
graph_lines = []
if graph_start != -1 and operation_start != -1:
    for i in range(graph_start + 1, operation_start):
        graph_lines.extend(parts[i].strip().split('\n'))
else:
    # Fallback: scan entire context
    for line in context.strip().split('\n'):
        line = line.strip()
        if '->' in line and not line.startswith("Operation:"):
            graph_lines.append(line)

# Extract operation
operation_text = ""
if operation_start != -1:
    operation_text = parts[operation_start].strip()
else:
    for line in context.strip().split('\n'):
        if line.strip().startswith("Operation:"):
            operation_text = line.strip()
            break

# Parse the operation to get target node
target_node = None
if "Find the parents of node" in operation_text:
    target_node = operation_text.split("node ")[1].strip()

# Parse edges
edges = []
for line in graph_lines:
    line = line.strip()
    if '->' in line:
        parts = line.split('->')
        if len(parts) == 2:
            source = parts[0].strip()
            dest = parts[1].strip()
            edges.append((source, dest))

print(f"Target node: {target_node}")
print(f"Number of edges: {len(edges)}")
print(f"Sample edges: {edges[:5]}")
print(f"Operation: {operation_text}")

# The target node is found in the edges, but not in the destinations list? That can't be.

# Let's print the exact edge where the target node appears
for source, dest in edges:
    if source == target_node or dest == target_node:
        print(f"Edge containing {target_node}: {source} -> {dest}")
